using Alterverse.Characters;using UnityEngine;
namespace Alterverse.Visuals
{
public static class StylizedHeroCard
{
public static void Draw(Rect rect,HeroId hero,Texture2D pixel,float time){if(pixel==null)return;Color accent=StylizedArtDirection.HeroAccent(hero);Color old=GUI.color;GUI.color=new Color(0,0,0,.58f);GUI.DrawTexture(rect,pixel);GUI.color=new Color(accent.r,accent.g,accent.b,.16f);GUI.DrawTexture(new Rect(rect.x+3,rect.y+3,rect.width-6,rect.height-6),pixel);DrawFractureFrame(rect,pixel,accent,time);float cx=rect.center.x,top=rect.y+rect.height*.17f,bodyY=rect.y+rect.height*.48f;float shoulder=(hero==HeroId.Kaelon||hero==HeroId.Rook)?.27f:.20f;float pulse=1f+Mathf.Sin(time*2f)*.04f;GUI.color=StylizedArtDirection.Ink;GUI.DrawTexture(new Rect(cx-rect.width*.105f,top,rect.width*.21f,rect.height*.19f),pixel);GUI.DrawTexture(new Rect(cx-rect.width*shoulder,bodyY,rect.width*shoulder*2f,rect.height*.32f),pixel);GUI.color=accent;GUI.DrawTexture(new Rect(cx-rect.width*.07f,bodyY+rect.height*.04f,rect.width*.14f,rect.height*.07f),pixel);switch(hero){case HeroId.Veyr:Cut(pixel,cx-rect.width*.22f,bodyY+rect.height*.03f,rect.width*.035f,rect.height*.34f,accent);Cut(pixel,cx+rect.width*.18f,bodyY-rect.height*.01f,rect.width*.035f,rect.height*.38f,StylizedArtDirection.ZeroEnergy);break;case HeroId.Kaelon:Cut(pixel,cx-rect.width*.34f,bodyY,rect.width*.12f,rect.height*.25f,accent);Cut(pixel,cx+rect.width*.22f,bodyY,rect.width*.12f,rect.height*.25f,accent);break;case HeroId.Nyra:Cut(pixel,cx+rect.width*.18f,bodyY+rect.height*.03f,rect.width*.06f,rect.height*.42f,accent);Cut(pixel,cx+rect.width*.23f,bodyY+rect.height*.34f,rect.width*.035f,rect.height*.18f,StylizedArtDirection.WarmAccent);break;case HeroId.Elyra:Orb(pixel,cx-rect.width*.29f,bodyY,rect.width*.08f*pulse,accent);Orb(pixel,cx+rect.width*.29f,bodyY+rect.height*.18f,rect.width*.06f*pulse,StylizedArtDirection.LumenEnergy);break;case HeroId.Mira:Cut(pixel,cx-rect.width*.31f,bodyY+rect.height*.05f,rect.width*.16f,rect.height*.08f,accent);Cut(pixel,cx+rect.width*.15f,bodyY+rect.height*.05f,rect.width*.16f,rect.height*.08f,accent);break;case HeroId.Rook:Cut(pixel,cx+rect.width*.22f,bodyY+rect.height*.08f,rect.width*.2f,rect.height*.22f,accent);break;}GUI.color=new Color(1,1,1,.72f);GUI.DrawTexture(new Rect(rect.x+10,rect.y+9,rect.width*.28f,2),pixel);GUI.DrawTexture(new Rect(rect.xMax-rect.width*.2f-10,rect.yMax-11,rect.width*.2f,2),pixel);GUI.color=old;}
private static void DrawFractureFrame(Rect r,Texture2D p,Color accent,float time){float pulse=.35f+.15f*Mathf.Sin(time*1.7f);GUI.color=new Color(accent.r,accent.g,accent.b,pulse);GUI.DrawTexture(new Rect(r.x+4,r.y+4,3,r.height*.31f),p);GUI.DrawTexture(new Rect(r.xMax-7,r.yMax-r.height*.35f-4,3,r.height*.35f),p);for(int i=0;i<3;i++){float y=r.y+r.height*(.18f+i*.27f);float w=r.width*(.10f+i*.035f);GUI.DrawTexture(new Rect(r.x+7,y,w,2),p);GUI.DrawTexture(new Rect(r.xMax-w-7,y+r.height*.08f,w,2),p);}}
private static void Cut(Texture2D p,float x,float y,float w,float h,Color c){GUI.color=c;GUI.DrawTexture(new Rect(x,y,w,h),p);}private static void Orb(Texture2D p,float x,float y,float r,Color c){GUI.color=c;GUI.DrawTexture(new Rect(x-r,y-r,r*2,r*2),p);}
}
}
